using System.Net;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Mvc.Testing;

namespace SafeVault.Tests
{
    /// <summary>
    /// Integration tests that submit attack-style input through
    /// SafeVault's ASP.NET Core request pipeline.
    /// </summary>
    public class SecurityAttackIntegrationTests
    {
        /// <summary>
        /// Retrieves the antiforgery token generated by a SafeVault
        /// form so the test can submit a legitimate protected POST.
        /// </summary>
        private static async Task<string> GetAntiforgeryTokenAsync(
            HttpClient client,
            string formPath)
        {
            var response =
                await client.GetAsync(formPath);

            response.EnsureSuccessStatusCode();

            var html =
                await response.Content.ReadAsStringAsync();

            var match = Regex.Match(
                html,
                @"name=""__RequestVerificationToken""[^>]*value=""([^""]+)""");

            Assert.True(
                match.Success,
                "The form did not contain an antiforgery token.");

            return match.Groups[1].Value;
        }

        /// <summary>
        /// Confirms that a SQL-injection-style username submitted
        /// through the user-information form is rejected and does
        /// not reach the successful-submission response.
        /// </summary>
        [Fact]
        public async Task UserForm_SqlInjectionAttempt_IsRejected()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress =
                            new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(
                    client,
                    "/");

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "' OR 1=1 --",
                        ["Email"] = "attacker@example.com",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act
            var response =
                await client.PostAsync(
                    "/Home/Index",
                    formContent);

            // Assert
            Assert.Equal(
                HttpStatusCode.OK,
                response.StatusCode);

            var responseHtml =
                await response.Content.ReadAsStringAsync();

            Assert.Contains(
                "Username may contain only letters, numbers, spaces, periods, underscores, and hyphens.",
                responseHtml);

            Assert.DoesNotContain(
                "Submission Successful",
                responseHtml);
        }
        /// <summary>
        /// Confirms that XSS-style markup submitted through the
        /// user-information form is rejected by SafeVault validation.
        /// </summary>
        [Fact]
        public async Task UserForm_XssAttempt_IsRejected()
        {
            // Arrange
            using var factory =
                new WebApplicationFactory<Program>();

            using var client =
                factory.CreateClient(
                    new WebApplicationFactoryClientOptions
                    {
                        AllowAutoRedirect = false,
                        BaseAddress =
                            new Uri("https://localhost"),
                        HandleCookies = true
                    });

            var antiforgeryToken =
                await GetAntiforgeryTokenAsync(
                    client,
                    "/");

            using var formContent =
                new FormUrlEncodedContent(
                    new Dictionary<string, string>
                    {
                        ["Username"] = "<script>alert('XSS')</script>",
                        ["Email"] = "attacker@example.com",
                        ["__RequestVerificationToken"] =
                            antiforgeryToken
                    });

            // Act
            var response =
                await client.PostAsync(
                    "/Home/Index",
                    formContent);

            // Assert
            Assert.Equal(
                HttpStatusCode.OK,
                response.StatusCode);

            var responseHtml =
                await response.Content.ReadAsStringAsync();

            Assert.Contains(
                "Username may contain only letters, numbers, spaces, periods, underscores, and hyphens.",
                responseHtml);

            Assert.DoesNotContain(
                "Submission Successful",
                responseHtml);
        }
    }
}